"""Collect manuscript facts that already exist in the repository into paper_assets/manuscript_facts.md.

Nothing is computed from new experiments. Hand-written statements below were read from the files named next to them;
tables are read from the result CSVs, MANIFEST.md, the tracker and the deployment metadata. Anything not recorded in
the repository is written as NOT RECORDED. Run:  venv/bin/python scripts/build_manuscript_facts.py
App facts are read from the app-v2 worktree (../Creditrisk_app) when it is present."""
import json, re
from pathlib import Path
import pandas as pd

ROOT = Path(__file__).resolve().parent.parent
R = ROOT / "experiments" / "results"
APP = ROOT.parent / "Creditrisk_app"
OUT = ROOT / "paper_assets" / "manuscript_facts.md"
L = []


def w(*s):
    L.extend(s)


def md(df, floatfmt="{:.4f}"):
    cols = list(df.columns)
    rows = ["| " + " | ".join(str(c) for c in cols) + " |", "|" + "---|" * len(cols)]
    for r in df.itertuples(index=False):
        rows.append("| " + " | ".join((floatfmt.format(v) if isinstance(v, float) else str(v)).replace("|", "\\|") for v in r) + " |")
    return "\n".join(rows)


def csv(name, **kw):
    return pd.read_csv(R / name, **kw)


