# ---- 7 tables and figures
w("## 7. Tables T1-T17 and figures F1-F11", "",
  "From `paper_assets/MANIFEST.md` (id, what it shows = 'paper claim it supports', source CSVs). Producer of every asset: `experiments/export_paper_assets.py` (PNG 300 dpi + PDF for figures; CSV + bare and captioned LaTeX for tables); "
  "upstream scripts that write the source CSVs are listed from a text search of `experiments/*.py` for the CSV name.", "")
scripts = {p.name: p.read_text(errors="ignore") for p in (ROOT / "experiments").glob("*.py")}


def producers(src):
    out = set()
    for tok in re.split(r"[;,]", src):
        tok = tok.strip().split(" ")[0]
        stem = tok.replace(".csv", "").replace("*", "")
        if not tok.endswith(".csv") or not stem:
            continue
        stem = stem.rstrip("_")
        for n, t in scripts.items():
            if n != "export_paper_assets.py" and stem in t:
                out.add(n)
    return ", ".join(sorted(out)) or "see MANIFEST sources"


rows = []
for ln in (ROOT / "paper_assets" / "MANIFEST.md").read_text().splitlines():
    if ln.startswith("| T") or ln.startswith("| F"):
        p = ln.split("|")
        rows.append((p[1].strip(), p[2].strip(), p[4].strip(), p[6].strip(), "|".join(p[7:-1]).strip() or p[7].strip()))


def key(r):
    m = re.match(r"([TF])(\d+)([a-z]?)", r[0]); return (m.group(1) == "F", int(m.group(2)), m.group(3))


rows.sort(key=key)
w("| id | what it shows (claim it supports) | source(s) | produced by (upstream experiment scripts) |", "|---|---|---|---|")
for i, k, s, c, cap in rows:
    w(f"| {i} | {c.replace('|', '/')} | {s} | {producers(s)} |")
w("", "T14 (scorecard) and T15 (claims) are listed among the tables above; T14 is built from many CSVs and the tracker, T15 from the tracker's claim tables.", "")

