w("## 11. Numbers the paper may cite", "")
pg = csv("phase3b_profit_d3.csv")
sel = ["approve_all", "fixed_0.5", "youden", "f1_max", "elkan", "profit_max", "expected_profit", "recall_0.70", "recall_0.80"]
lgb = pg[(pg.model == "LightGBM") & pg.rule.isin(sel)]
for val, lab, fmt in (("profit_per_1000_mean", "Profit per 1000 applicants (USD, mean over 10 repeats)", "{:,.0f}"), ("accept_rate_mean", "Acceptance rate", "{:.3f}")):
    t = lgb.pivot(index="rule", columns="scenario", values=val).reindex(sel)[["P1", "P2_0%", "P2_2%", "P2_3%", "P2_5%", "P2_8%"]]
    t = t.reset_index()
    w(f"**Discount-rate grid, D3, LightGBM (isotonic), {lab}.** P1 = undiscounted; P2 at 0/2/3/5/8% p.a. Source: `phase3b_profit_d3.csv` (all five models, sd and bootstrap in the same CSV and `phase3b_profit_d3_bootstrap.csv`).", "")
    w(md(t, fmt), "")
th = lgb[lgb.rule.isin(["elkan", "profit_max", "youden", "f1_max"])].pivot(index="rule", columns="scenario", values="threshold_mean")[["P1", "P2_0%", "P2_2%", "P2_3%", "P2_5%", "P2_8%"]].reset_index()
w("Thresholds selected (mean over repeats; Elkan, profit-max, Youden, F1-max):", "", md(th), "")
w("**Per-model tables, D1 / D2 / D3** (unweighted models, 10 repeats for D2/D3 and 5 for D1; mean over repeats; tuned threshold = Youden on OOF raw scores; Brier here is of the RAW score; ECE is test-set ECE with 15 equal-frequency bins). "
  "Sources: `phase2_weighting_D1.csv`, `phase2_weighting_D2.csv`, `phase2_weighting_D3.csv` (AUC, PR-AUC, Brier, recall) and `phase2_calibration_D1.csv`, `phase2_calibration_D2.csv`, `phase2_calibration_D3.csv` (ECE).", "")
for ds in ("D1", "D2", "D3"):
    a = csv(f"phase2_weighting_{ds}.csv")
    a = a[(a.weighting == "none") & (a.thr_rule == "tuned")][["model", "ROC_AUC_mean", "PR_AUC_mean", "Brier_mean", "Recall_mean", "threshold_mean"]]
    b = csv(f"phase2_calibration_{ds}.csv")
    b = b[b.weighting == "none"].pivot(index="model", columns="calib", values="ECE_mean")[["raw", "platt", "isotonic"]].add_prefix("ECE_").reset_index()
    t = a.merge(b, on="model").rename(columns={"ROC_AUC_mean": "ROC-AUC", "PR_AUC_mean": "PR-AUC", "Brier_mean": "Brier (raw)", "Recall_mean": "recall @ tuned t", "threshold_mean": "mean tuned t"})
    w(f"**{ds}**", "", md(t), "")
